export function ImageViewer({
  altText = "{{altText}}",
  position = "{{position}}",
  zoomedIn = {{zoomedIn}},
  accent = "{{accent}}",
}) {
  return (
    <figure style={{ font: "12px/1.4 system-ui, sans-serif", color: "#FAF7F2", width: 320, margin: 0, borderRadius: 10, overflow: "hidden", boxSizing: "border-box", background: "#24143008" }}>
      <div style={{ width: "100%", height: 160, overflow: "hidden" }}>
        <svg className="iv-svg" width="100%" height="100%" viewBox="0 0 200 120" preserveAspectRatio="none" aria-hidden="true" style={{ display: "block", transform: zoomedIn ? "scale(1.4)" : "none" }}>
          <rect width="200" height="120" fill="#D9C8F0" /><circle cx="164" cy="26" r="14" fill="#E8A020" /><path d="M0 100l50-50 40 34 30-26 80 42Z" fill="#A8E6C1" />
        </svg>
      </div>
      <figcaption style={{ display: "flex", justifyContent: "space-between", gap: 10, padding: "8px 12px", background: accent }}>
        <span style={{ fontWeight: 700 }}>Image {position} of 5</span>
        <span style={{ opacity: .8, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{altText}</span>
      </figcaption>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .iv-svg { transition: transform .15s; }
        }
      `}</style>
    </figure>
  );
}
